<script setup>
import { ref, reactive, computed, onMounted, onUnmounted } from 'vue';
import { api, setCsrf } from './api';
const user=ref(null),tab=ref('market'),feedback=ref('准备好了。从一件闲置物品，开始一次校园循环。'),error=ref(false),busy=ref(false);
const items=ref([]),mine=ref([]),orders=ref([]),favorites=ref([]),verifications=ref([]),disputes=ref([]),reports=ref([]),notifications=ref([]),inbox=ref([]),management=ref(null),statistics=ref(null);
const query=ref(''),category=ref(''),page=ref(1),adminTab=ref('items');
const categories=['教材书籍','数码配件','宿舍生活','运动户外','其他'];
const dialog=ref(null),fields=reactive({}),chat=ref(null),messages=ref([]),messageText=ref(''),publicReviews=ref(null),registerMode=ref(false);
const login=reactive({username:'',password:'',nickname:''});
const itemForm=reactive({id:'',title:'',category:'教材书籍',description:'',price:'',image_id:''});
const verifyForm=reactive({student_no:'',real_name:'',asset_id:''});
const dateFilter=reactive({from:'',to:''});
const isAdmin=computed(()=>user.value?.role==='ADMIN');
const done=computed(()=>orders.value.filter(o=>o.stage==='已完成'));
const active=computed(()=>orders.value.filter(o=>['待卖方确认','待交付','待买方确认'].includes(o.stage)));
const money=n=>Number(n||0).toFixed(2);
const date=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const short=v=>v?.slice(0,8);
function say(text,failed=false){feedback.value=text;error.value=failed;}
function clearPrivate(){orders.value=[];mine.value=[];favorites.value=[];verifications.value=[];disputes.value=[];reports.value=[];notifications.value=[];inbox.value=[];management.value=null;statistics.value=null;chat.value=null;}
async function safe(fn){if(busy.value)return;busy.value=true;try{await fn();}catch(e){
 if(e.status===401||e.status===403){try{const me=await api('/me');const old=user.value?.id;user.value=me.user;setCsrf(me.csrf);if(old!==me.user?.id){clearPrivate();tab.value='market';dialog.value=null;} }catch{}}
 say(e.message,true);
}finally{busy.value=false;}}
let searchVersion=0;
async function market(){const version=++searchVersion;const rows=await api(`/items?q=${encodeURIComponent(query.value)}&category=${encodeURIComponent(category.value)}&page=${page.value}`);if(version===searchVersion)items.value=rows;}
async function refresh(){
 const me=await api('/me');const old=user.value?.id;user.value=me.user;setCsrf(me.csrf);
 if(old!==me.user?.id){clearPrivate();dialog.value=null;tab.value='market';}
 await market();
 if(user.value){const result=await Promise.all(['/items/mine','/orders','/favorites','/verifications','/disputes','/reports','/notifications','/inbox'].map(p=>api(p)));[mine.value,orders.value,favorites.value,verifications.value,disputes.value,reports.value,notifications.value,inbox.value]=result;if(isAdmin.value&&tab.value==='admin')await loadAdmin();}
}
async function loadAdmin(){[management.value,statistics.value]=await Promise.all([api('/admin/dashboard'),api('/admin/stats'+statsParams())]);}
function statsParams(){const p=new URLSearchParams();if(dateFilter.from)p.set('from',new Date(dateFilter.from).toISOString());if(dateFilter.to)p.set('to',new Date(dateFilter.to).toISOString());return '?'+p;}
async function navigate(next){if(next!=='market'&&!user.value){openLogin();return;}tab.value=next;await safe(async()=>{await refresh();});}
function openLogin(){error.value=false;dialog.value={type:'login',title:registerMode.value?'注册校园账户':'欢迎回到校园循环'};}
async function authenticate(){await safe(async()=>{const data=await api('/auth/'+(registerMode.value?'register':'login'),'POST',login);user.value=data.user;setCsrf(data.csrf);login.password='';dialog.value=null;await refresh();say('你好，'+user.value.nickname+'。');});}
async function logout(){await safe(async()=>{await api('/auth/logout','POST',{});user.value=null;tab.value='market';chat.value=null;orders.value=[];mine.value=[];favorites.value=[];verifications.value=[];disputes.value=[];reports.value=[];notifications.value=[];inbox.value=[];management.value=null;statistics.value=null;dialog.value=null;const me=await api('/me');setCsrf(me.csrf);await market();say('已退出登录。');});}
function open(title,form,submit,help=''){error.value=false;Object.keys(fields).forEach(k=>delete fields[k]);form.forEach(f=>fields[f.key]=f.value??(f.type==='check'?false:''));dialog.value={title,form,submit,help};}
async function submitDialog(){await safe(async()=>{const current=dialog.value;await current.submit({...fields});dialog.value=null;await refresh();say('操作已保存。');});}
async function command(path,body){const storageKey='campus:last:'+user.value.id;const fingerprint=JSON.stringify({path,body});let saved;try{saved=JSON.parse(sessionStorage.getItem(storageKey)||'null');}catch{}if(!saved||saved.fingerprint!==fingerprint){saved={fingerprint,key:crypto.randomUUID()};sessionStorage.setItem(storageKey,JSON.stringify(saved));}const result=await api(path,'POST',body,saved.key);sessionStorage.removeItem(storageKey);return result;}
function buy(item){if(!user.value)return openLogin();open('确认下单',[{key:'declared',type:'check',label:`我已确认「${item.title}」及价格 ¥${money(item.price)}`,required:true}],async()=>{await command('/orders',{item_id:item.id,version:item.version});},'下单会预占这件物品。款项由双方线下结算，平台不收款。');}
function orderAction(o,action){
 const titles={accept:'接受订单',reject:'拒绝订单',deliver:'登记交付',confirm:'确认收到',cancel:'取消订单',remind:'提醒买方'};
 const form=[];if(['reject','deliver','cancel'].includes(action))form.push({key:'reason',label:action==='deliver'?'交付记录（时间、地点、说明）':'原因',type:'textarea',required:true,max:1000});
 if(['deliver','confirm','cancel'].includes(action))form.push({key:'declared',label:action==='deliver'?'我确认已经实际交付物品':action==='confirm'?'我本人已经收到物品':'我声明尚未实际交付；若已交付或有分歧，应申请争议处理',type:'check',required:true});
 open(titles[action],form,async b=>{await command(`/orders/${o.id}/${action}`,b);},action==='deliver'?'登记交付后仍须买方本人确认，才计入成交。':'操作会按当前订单阶段和本人权限进行检查。');
}
function buttons(o){const seller=o.seller_id===user.value?.id;if(o.stage==='待卖方确认')return o.disputed?[]:seller?[['accept','接单'],['reject','拒单']]:[['cancel','取消']];if(o.stage==='待交付')return o.disputed?[]:seller?[['deliver','登记交付'],['cancel','取消']]:[['cancel','取消']];if(o.stage==='待买方确认')return seller?(o.reminded?[]:[['remind','提醒买方']]):[['confirm','确认收到']];return [];}
async function upload(event,kind,target,key){const file=event.target.files[0];if(!file)return;await safe(async()=>{const form=new FormData();form.append('file',file);form.append('kind',kind);const result=await api('/assets','POST',form);target[key]=result.id;say('图片上传完成。');});}
function editItem(item){Object.assign(itemForm,{id:item.id,title:item.title,category:item.category,description:item.description,price:item.price,image_id:item.image_id});tab.value='publish';}
function newItem(){Object.assign(itemForm,{id:'',title:'',category:'教材书籍',description:'',price:'',image_id:''});navigate('publish');}
async function publish(){await safe(async()=>{const {id,...body}=itemForm;await api(id?'/items/'+id:'/items',id?'PUT':'POST',body);Object.assign(itemForm,{id:'',title:'',category:'教材书籍',description:'',price:'',image_id:''});await refresh();tab.value='mine';say('物品已提交，当前版本审核通过后才会公开展示。');});}
async function verify(){await safe(async()=>{await api('/verifications','POST',verifyForm);Object.assign(verifyForm,{student_no:'',real_name:'',asset_id:''});await refresh();say('校园认证已提交，请等待管理员审核。');});}
function withdraw(item){open('撤下物品',[{key:'confirm',type:'check',label:'确认撤下，保留历史记录',required:true}],()=>api('/items/'+item.id+'/withdraw','POST',{}));}
function favorite(item){if(!user.value)return openLogin();safe(async()=>{await api('/favorites/'+item.id,'POST',{});await refresh();say('收藏已更新。');});}
function reportObject(type,id){if(!user.value)return openLogin();open('提交举报',[{key:'reason',label:'举报事实与理由',type:'textarea',required:true,max:1500},{key:'evidence',label:'证据说明',type:'textarea',max:1500}],b=>api('/reports','POST',{...b,object_type:type,object_id:id}),'同事件可关联核查；每条举报保留独立回执，举报数量不直接判定违规。');}
function startDispute(o){open('申请履约争议处理',[{key:'reason',label:'履约分歧或已交付未登记情况',type:'textarea',required:true,max:1500},{key:'evidence',label:'相关证据、时间和情况',type:'textarea',max:1500}],b=>api('/orders/'+o.id+'/disputes','POST',b),'受理后保留订单原阶段和占用，暂停接单、拒单、登记和普通取消。已登记时买方仍可确认收到。');}
function supplement(d){open('补充争议证据',[{key:'evidence',label:'新增证据与事实',type:'textarea',required:true,max:1500}],b=>api('/disputes/'+d.id+'/evidence','POST',b));}
function review(o){open('评价本次交易',[{key:'score',label:'评分',type:'select',options:['5','4','3','2','1'],value:'5',required:true},{key:'content',label:'评价内容（请勿包含联系方式和个人身份信息）',type:'textarea',required:true,max:1000}],b=>api('/orders/'+o.id+'/reviews','POST',b),'完成订单双方各可评价一次。');}
async function viewReviews(seller){await safe(async()=>{publicReviews.value=await api('/sellers/'+seller+'/reviews');});}
async function openChat(type,object,peer='',title='交易沟通'){if(!user.value)return openLogin();chat.value={type,object,peer,title};messages.value=[];messageText.value='';await safe(loadMessages);}
async function loadMessages(){if(!chat.value)return;const current=chat.value;const data=await api('/messages?'+new URLSearchParams(current));if(chat.value===current)messages.value=data;}
async function send(){await safe(async()=>{await api('/messages?'+new URLSearchParams(chat.value),'POST',{content:messageText.value});messageText.value='';await loadMessages();});}
function manage(kind,obj,extra={},title='管理处置'){const form=[{key:'reason',label:'审核或核查依据与原因',type:'textarea',required:true,max:1500}];if(kind==='dispute'){form.push({key:'outcome',label:'处置结果',type:'select',options:['continue','terminate'],labels:['继续履约，保留原阶段','有依据异常终止'],value:'continue',required:true},{key:'evidence_confirmed',label:'若异常终止，我已核查无法履约依据；不以沉默作为唯一依据',type:'check'});}if(kind==='report')form.push({key:'event_ref',label:'同事件关联编号（可选）',type:'text',max:100});open(title,form,b=>api(`/admin/${kind}/${obj}`,'POST',{...extra,...b}));}
function isFavorite(id){return favorites.value.some(i=>i.id===id);}
let poll;
onMounted(async()=>{await safe(async()=>{const me=await api('/me');user.value=me.user;setCsrf(me.csrf);await refresh();});poll=setInterval(()=>{if(chat.value&&!busy.value)loadMessages().catch(e=>say(e.message,true));},5000);});
onUnmounted(()=>clearInterval(poll));
</script>

<template>
 <header><a class="brand" href="#" @click.prevent="navigate('market')"><span class="mark">循</span><span><strong>校园循环</strong><small>让闲置物品，遇见下一位同学</small></span></a><div class="identity" v-if="user"><span>{{ user.nickname }} <span class="tag" :class="{warn:user.restricted}">{{ user.restricted?'账户受限':user.verified?'校园已认证':'待认证' }}</span></span><button @click="logout" :disabled="busy">退出</button></div><button v-else class="primary" @click="openLogin">登录 / 注册</button></header>
 <div class="notice">校园单件二手物品交易 · 校内线下交付与结算 · 卖方登记交付，买方本人确认收到</div>
 <main>
  <nav aria-label="主导航"><button :class="{active:tab==='market'}" @click="navigate('market')">发现物品</button><button :class="{active:tab==='mine'||tab==='publish'}" @click="navigate('mine')">我的发布</button><button :class="{active:tab==='orders'}" @click="navigate('orders')">我的订单</button><button :class="{active:tab==='messages'}" @click="navigate('messages')">消息</button><button :class="{active:tab==='account'}" @click="navigate('account')">个人中心</button><button v-if="isAdmin" :class="{active:tab==='admin'}" @click="navigate('admin')">管理台</button></nav>
  <div id="feedback" role="status" aria-live="polite" :class="{error}">{{ busy?'正在处理，请稍候…':feedback }}<button class="refresh" :disabled="busy" @click="safe(refresh)">刷新</button></div>
  <section v-if="tab==='market'">
   <div class="intro"><div><span class="eyebrow">CAMPUS CIRCULATION</span><h1>旧物有新去处，好物继续发光。</h1><p class="muted">找一本需要的书，也让不再需要的物品继续被珍惜。</p></div><button class="primary" @click="newItem">＋ 发布闲置</button></div>
   <form class="search" @submit.prevent="page=1;safe(market)"><input v-model="query" maxlength="120" placeholder="搜索教材、台灯、数码配件…" aria-label="搜索物品"><button class="primary" :disabled="busy">搜索物品</button></form>
   <div class="chips"><button v-for="c in ['',...categories]" :key="c" :class="{active:category===c}" :aria-pressed="category===c" @click="category=c;page=1;safe(market)">{{ c||'全部物品' }}</button></div>
   <div class="grid"><article class="card item-card" v-for="i in items" :key="i.id"><img :src="'/api/assets/'+i.image_id" :alt="i.title" class="item-image"><div class="row"><span class="tag">{{ i.category }}</span><span class="muted small">{{ i.seller_name }} · 校园认证</span></div><h2>{{ i.title }}</h2><p class="description">{{ i.description }}</p><div class="row"><div class="price">¥ {{ money(i.price) }}</div><button class="primary" :disabled="busy" @click="buy(i)">确认下单</button></div><div class="actions compact"><button @click="favorite(i)">{{ isFavorite(i.id)?'已收藏':'收藏' }}</button><button @click="openChat('ITEM',i.id,'',i.title)">咨询卖方</button><button @click="viewReviews(i.seller_id)">卖方评价</button><button @click="reportObject('ITEM',i.id)">举报</button></div></article></div>
   <div class="empty" v-if="!items.length"><strong>暂时没有找到物品</strong><p>换个关键词，或等待新物品审核上架。</p></div><div class="pagination"><button :disabled="page<=1||busy" @click="page--;safe(market)">上一页</button><span>第 {{ page }} 页</span><button :disabled="items.length<20||busy" @click="page++;safe(market)">下一页</button></div>
  </section>
  <section v-if="tab==='mine'"><div class="intro"><div><h1>我的发布</h1><p class="muted">每次关键修改都生成新版本，重新审核。</p></div><button class="primary" @click="newItem">＋ 发布闲置</button></div><div class="grid"><article class="card" v-for="i in mine" :key="i.id"><div class="row"><span class="tag">{{ i.status }}{{ i.hidden?' · 已隐藏':'' }}</span><span class="muted">版本 {{ i.version }}</span></div><h2>{{ i.title }}</h2><p class="price">¥ {{ money(i.price) }}</p><p>{{ i.reason||'暂无审核意见' }}</p><div class="actions"><button v-if="['在售','待审','审核退回','已撤下','交易异常终止'].includes(i.status)" @click="editItem(i)">修改 / 重新提交</button><button v-if="['在售','待审','审核退回'].includes(i.status)" @click="withdraw(i)">撤下</button></div></article></div><div class="empty" v-if="!mine.length">还没有发布物品，试着发布第一件闲置吧。</div></section>
  <section v-if="tab==='publish'"><div class="intro"><div><h1>{{ itemForm.id?'修改并重新审核':'发布一件闲置' }}</h1><p class="muted">单件实物、正数价格，审核通过后公开。有效订单期间不能修改。</p></div></div><form class="card form" @submit.prevent="publish"><label>物品名称<input v-model="itemForm.title" required maxlength="120"></label><div class="form-grid"><label>分类<select v-model="itemForm.category"><option v-for="c in categories" :key="c">{{ c }}</option></select></label><label>价格 / 元<input type="number" min="0.01" max="9999999999.99" step="0.01" v-model="itemForm.price" required></label></div><label>物品描述<textarea v-model="itemForm.description" rows="5" required maxlength="5000" placeholder="成色、使用情况、瑕疵等，请如实说明。不要填写公开联系方式。"></textarea></label><label>物品图片（JPEG / PNG，最大 5MB）<input type="file" accept="image/png,image/jpeg" @change="upload($event,'ITEM',itemForm,'image_id')"></label><img class="preview" v-if="itemForm.image_id" :src="'/api/assets/'+itemForm.image_id" alt="物品图片预览"><div class="actions"><button class="primary" :disabled="busy||!itemForm.image_id">提交审核</button><button type="button" @click="navigate('mine')">返回</button></div></form></section>
  <section v-if="tab==='orders'"><div class="intro"><div><h1>我的订单</h1><p class="muted">订单保留成立时的物品与价格快照。交付登记不等于成交。</p></div><span class="tag">进行中 {{ active.length }} · 已完成 {{ done.length }}</span></div><article class="card" v-for="o in orders" :key="o.id"><div class="row"><span class="tag">{{ o.stage }}{{ o.disputed?' · 争议处理中':'' }}</span><span class="muted small">{{ date(o.created_at) }} · {{ short(o.id) }}</span></div><h2>{{ o.title }}</h2><p class="description">{{ o.description }}</p><div class="row"><span class="price">¥ {{ money(o.price) }}</span><span class="muted">买方 {{ o.buyer_name }} ／ 卖方 {{ o.seller_name }}</span></div><div class="steps"><span v-for="stage in ['待卖方确认','待交付','待买方确认','已完成']" :key="stage" :class="{current:o.stage===stage}">{{ stage }}</span></div><p v-if="o.reason" class="muted">操作原因：{{ o.reason }}</p><div class="actions"><button class="primary" :disabled="busy" v-for="[key,label] in buttons(o)" :key="key" @click="orderAction(o,key)">{{ label }}</button><button @click="openChat('ORDER',o.id,'',o.title)">{{ ['已完成','已取消','已拒绝','已异常终止'].includes(o.stage)?'查看历史沟通':'订单沟通' }}</button><button v-if="['待卖方确认','待交付','待买方确认'].includes(o.stage)&&!o.disputed" @click="startDispute(o)">申请争议处理</button><button v-if="o.stage==='已完成'" @click="review(o)">评价交易</button><button @click="reportObject('ORDER',o.id)">举报反馈</button></div></article><div class="empty" v-if="!orders.length">还没有订单，去发现物品逛逛吧。</div><h2 v-if="disputes.length">我的履约争议</h2><article class="card" v-for="d in disputes" :key="d.id"><div class="row"><strong>订单 {{ short(d.order_id) }}</strong><span class="tag">{{ d.status }}</span></div><p>{{ d.reason }}</p><pre class="evidence">{{ d.evidence }}</pre><p v-if="d.decision">{{ d.outcome }}：{{ d.decision }}</p><button v-if="d.status==='处理中'" @click="supplement(d)">补充证据</button></article></section>
  <section v-if="tab==='messages'"><div class="intro"><div><h1>消息与通知</h1><p class="muted">咨询与订单沟通分别保存，终态订单会话只读。</p></div></div><div class="grid"><div><h2>会话</h2><article class="card row" v-for="c in inbox" :key="c.context_type+c.context_id+c.peer_id"><span>{{ c.context_type==='ORDER'?'订单沟通':'物品咨询' }} · {{ short(c.context_id) }}</span><button @click="openChat(c.context_type,c.context_id,c.peer_id)">打开</button></article><div class="empty" v-if="!inbox.length">暂无会话，可从物品或订单发起沟通。</div></div><div><h2>站内通知</h2><article class="card" v-for="n in notifications" :key="n.id"><p>{{ n.content }}</p><small class="muted">{{ date(n.created_at) }}</small></article><div class="empty" v-if="!notifications.length">暂无通知。</div></div></div></section>
  <section v-if="tab==='account'&&user"><div class="intro"><div><h1>{{ user.nickname }}的个人中心</h1><p class="muted">账号 {{ user.username }} · {{ user.verified?'校园认证已通过':'尚未通过校园认证' }}</p></div></div><div class="grid"><div><form v-if="!user.verified" class="card form" @submit.prevent="verify"><h2>校园身份认证</h2><p class="muted">材料只供本人及授权审核人员查看。</p><label>真实姓名<input v-model="verifyForm.real_name" required maxlength="50"></label><label>学号<input v-model="verifyForm.student_no" required maxlength="50"></label><label>认证材料图片<input type="file" accept="image/jpeg,image/png" @change="upload($event,'VERIFY',verifyForm,'asset_id')"></label><p v-if="verifyForm.asset_id" class="tag">材料已上传</p><button class="primary" :disabled="busy||!verifyForm.asset_id">提交认证</button></form><article class="card" v-for="v in verifications" :key="v.id"><div class="row"><strong>认证申请</strong><span class="tag">{{ v.status }}</span></div><p>{{ v.reason||'等待审核' }}</p><small class="muted">{{ date(v.created_at) }}</small></article><h2>我的举报回执</h2><article class="card" v-for="r in reports" :key="r.id"><span class="tag">{{ r.status }}</span><p>{{ r.reason }}</p><p class="muted">{{ r.result||'等待核查' }}</p><small>回执 {{ short(r.id) }}</small></article><div v-if="!reports.length" class="empty">暂无举报记录。</div></div><div><h2>我的收藏</h2><article class="card row" v-for="i in favorites" :key="i.id"><div><strong>{{ i.title }}</strong><p class="muted">¥ {{ money(i.price) }} · {{ i.status }}</p></div><button @click="favorite(i)">取消收藏</button></article><div class="empty" v-if="!favorites.length">收藏喜欢的物品，方便下次寻找。</div></div></div></section>
  <section v-if="tab==='admin'&&isAdmin&&management"><div class="intro"><div><h1>校园管理台</h1><p class="muted">审核当前版本，处置保留依据；管理员不能代买方确认收货。</p></div></div><div class="stats" v-if="statistics"><div><strong>{{ statistics.sales.count }}</strong><span>完成订单</span></div><div><strong>¥ {{ money(statistics.sales.amount) }}</strong><span>快照成交额</span></div><div><strong>{{ statistics.items.count }}</strong><span>累计发布</span></div><div><strong>{{ statistics.reports.count }}</strong><span>累计举报</span></div></div><form class="search range" @submit.prevent="safe(async()=>statistics=await api('/admin/stats'+statsParams()))"><label>成交开始<input type="datetime-local" v-model="dateFilter.from"></label><label>成交截止（不含）<input type="datetime-local" v-model="dateFilter.to"></label><button :disabled="busy">筛选成交统计</button></form><p class="muted small" v-if="statistics">{{ statistics.basis }}</p><div class="chips"><button v-for="[key,label] in [['items','物品审核'],['verifications','校园认证'],['accounts','账户治理'],['disputes','履约争议'],['reports','举报处理'],['reviews','评价治理'],['logs','操作记录']]" :key="key" :class="{active:adminTab===key}" @click="adminTab=key">{{ label }}</button></div>
   <template v-if="adminTab==='items'"><article class="card" v-for="i in management.items" :key="i.id"><div class="row"><h2>{{ i.title }}</h2><span class="tag">{{ i.status }}{{ i.hidden?' · 隐藏':'' }}</span></div><p>{{ i.description }}</p><p class="muted">{{ i.seller_name }} · ¥ {{ money(i.price) }} · 版本 {{ i.version }}</p><a :href="'/api/assets/'+i.image_id" target="_blank" rel="noopener">查看图片</a><div class="actions"><template v-if="i.status==='待审'"><button class="primary" @click="manage('item',i.id,{pass:true,version:i.version},'审核通过当前版本')">通过</button><button @click="manage('item',i.id,{pass:false,version:i.version},'退回当前版本')">退回</button></template><button @click="manage('hide',i.id,{hidden:!i.hidden},i.hidden?'解除隐藏':'隐藏物品')">{{ i.hidden?'解除隐藏':'隐藏物品' }}</button><button v-if="i.status==='交易异常终止'&&!i.relist_allowed" @click="manage('relist',i.id,{},'核实归属，允许重新提交')">核实归属</button></div></article></template>
   <template v-if="adminTab==='verifications'"><article class="card" v-for="v in management.verifications" :key="v.id"><div class="row"><h2>{{ v.nickname }} · {{ v.real_name }}</h2><span class="tag">{{ v.status }}</span></div><p>学号：{{ v.student_no }}</p><a :href="'/api/assets/'+v.asset_id" target="_blank" rel="noopener">查看认证材料（私有）</a><p>{{ v.reason }}</p><div class="actions" v-if="v.status==='待审'"><button class="primary" @click="manage('verification',v.id,{pass:true},'通过校园认证')">通过</button><button @click="manage('verification',v.id,{pass:false},'退回校园认证')">退回</button></div></article></template>
   <template v-if="adminTab==='accounts'"><article class="card row" v-for="u in management.accounts" :key="u.id"><div><strong>{{ u.nickname }}</strong><p class="muted">{{ u.username }} · {{ u.verified?'已认证':'未认证' }} · {{ u.restricted?'受限':'正常' }}</p></div><button v-if="u.role!=='ADMIN'" @click="manage('restrict',u.id,{restricted:!u.restricted},u.restricted?'恢复账户':'限制账户')">{{ u.restricted?'恢复':'限制' }}</button><span v-else class="tag">管理员</span></article></template>
   <template v-if="adminTab==='disputes'"><article class="card" v-for="d in management.disputes" :key="d.id"><div class="row"><h2>{{ d.title }}</h2><span class="tag">{{ d.status }} · {{ d.stage }}</span></div><p>{{ d.reason }}</p><pre class="evidence">{{ d.evidence }}</pre><p v-if="d.decision">{{ d.outcome }}：{{ d.decision }}</p><button v-if="d.status==='处理中'" @click="manage('dispute',d.id,{},'核查并结案履约争议')">核查结案</button></article></template>
   <template v-if="adminTab==='reports'"><article class="card" v-for="r in management.reports" :key="r.id"><div class="row"><strong>{{ r.object_type }} · {{ short(r.object_id) }}</strong><span class="tag">{{ r.status }}</span></div><p>{{ r.reason }}</p><pre class="evidence">{{ r.evidence }}</pre><p>{{ r.result }}</p><p v-if="r.event_ref" class="muted">事件关联：{{ r.event_ref }}</p><button @click="manage('report',r.id,{},'记录举报核查结果')">处理 / 复核新增事实</button></article></template>
   <template v-if="adminTab==='reviews'"><article class="card" v-for="r in management.reviews" :key="r.id"><span class="tag">{{ r.score }} 分 · {{ r.hidden?'已隐藏':'公开' }}</span><p>{{ r.content }}</p><button @click="manage('review',r.id,{hidden:!r.hidden},'评价展示治理')">{{ r.hidden?'恢复公开':'隐藏评价' }}</button></article></template>
   <template v-if="adminTab==='logs'"><article class="log" v-for="l in management.logs" :key="l.id"><strong>{{ l.action }}</strong><span>{{ l.nickname }} · {{ date(l.created_at) }} · {{ short(l.object_id) }}</span><p>{{ l.reason }}</p></article></template><div v-if="!management[adminTab]?.length" class="empty">暂无相关记录。</div>
  </section>
  <footer>校园循环 · 交易款项由当事人线下结算。平台记录审核、交易与治理过程。<br>公开信息不包含真实姓名、学号、认证材料或私人联系方式。</footer>
 </main>
 <div v-if="dialog" class="backdrop" @click.self="!busy&&(dialog=null)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">{{ dialog.title }}</h2><template v-if="dialog.type==='login'"><form class="form" @submit.prevent="authenticate"><label>账号<input v-model="login.username" autocomplete="username" required minlength="3" maxlength="40" autofocus></label><label>密码<input v-model="login.password" type="password" :autocomplete="registerMode?'new-password':'current-password'" required minlength="8" maxlength="72"></label><label v-if="registerMode">昵称<input v-model="login.nickname" required maxlength="30"></label><p class="muted small">首次本地演示账号：admin / seller / buyer / buyer2<br>演示密码：Campus123!</p><p v-if="error" role="alert" class="inline-error">{{ feedback }}</p><div class="actions"><button class="primary" :disabled="busy">{{ registerMode?'注册':'登录' }}</button><button type="button" :disabled="busy" @click="registerMode=!registerMode;dialog.title=registerMode?'注册校园账户':'欢迎回到校园循环'">{{ registerMode?'已有账号':'注册新账号' }}</button><button type="button" :disabled="busy" @click="dialog=null">返回</button></div></form></template><form v-else class="form" @submit.prevent="submitDialog"><p class="muted">{{ dialog.help }}</p><label v-for="f in dialog.form" :key="f.key" :class="{check:f.type==='check'}"><template v-if="f.type==='check'"><input type="checkbox" v-model="fields[f.key]" :required="f.required">{{ f.label }}</template><template v-else>{{ f.label }}<textarea v-if="f.type==='textarea'" v-model="fields[f.key]" rows="4" :required="f.required" :maxlength="f.max||1500"></textarea><select v-else-if="f.type==='select'" v-model="fields[f.key]" :required="f.required"><option v-for="(o,i) in f.options" :key="o" :value="o">{{ f.labels?.[i]||o }}</option></select><input v-else v-model="fields[f.key]" :required="f.required" :maxlength="f.max||200"></template></label><p v-if="error" role="alert" class="inline-error">{{ feedback }}</p><div class="actions end"><button type="button" :disabled="busy" @click="dialog=null">返回</button><button class="primary" :disabled="busy">确认提交</button></div></form></section></div>
 <div v-if="chat" class="backdrop" @click.self="chat=null"><section class="modal chat-modal" role="dialog" aria-modal="true" aria-labelledby="chat-title"><div class="row"><h2 id="chat-title">{{ chat.title }}</h2><button @click="chat=null">关闭</button></div><p class="muted small">仅会话双方可见 · 订单结束后只读 · 每 5 秒更新</p><div class="messages"><article v-for="m in messages" :key="m.id" :class="{self:m.sender_id===user?.id}"><small>{{ m.sender_name }} · {{ date(m.created_at) }}</small><p>{{ m.content }}</p></article><p v-if="!messages.length" class="muted">暂无消息。</p></div><form class="search" @submit.prevent="send"><input v-model="messageText" required maxlength="1500" aria-label="消息内容" placeholder="约定校内交接或补充情况…"><button class="primary" :disabled="busy">发送</button></form><p v-if="error" class="inline-error">{{ feedback }}</p></section></div>
 <div v-if="publicReviews!==null" class="backdrop" @click.self="publicReviews=null"><section class="modal" role="dialog" aria-modal="true" aria-label="卖方公开评价"><div class="row"><h2>卖方公开评价</h2><button @click="publicReviews=null">关闭</button></div><article class="log" v-for="(r,i) in publicReviews" :key="i"><strong>{{ r.score }} 分 · {{ r.nickname }}</strong><p>{{ r.content }}</p><small>{{ date(r.created_at) }}</small></article><p v-if="!publicReviews.length" class="empty">暂无公开评价。</p></section></div>
</template>
